class HarmonicSphere:

    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Ensure the input is within bounds [-5.0, 5.0] per dimension
        x = np.clip(x, -5.0, 5.0)
        # Compute the Euclidean distance from the origin
        r = np.linalg.norm(x)
        # Harmonic scaling factor to control basin sizes
        harmonic_factor = 1.0 / (1 + r) if r > 0 else 1.0
