import numpy as np

class HarmonicSphere:

    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Ensure x is a numpy array for vectorized operations
        x = np.asarray(x)
        if len(x) != self.dim:
            raise ValueError(f"Expected input of dimension {self.dim}, got {len(x)}")

        # Harmonic scaling factor based on distance from origin
        r = np.linalg.norm(x)
        if r == 0:
            return 0.0

        # Harmonic term: 1/r^2 ensures basins scale harmonically with distance
        harmonic_term = (x / r) ** 2 * (1 + 1/(r**2))

        # Quadratic term for smoothness near origin
        quadratic_term = x**2

        return np.sum(quadratic_term + harmonic_term)

import numpy as np

class SphericalHarmonicBasinLattice:
    """
    Spherical Harmonic Basin Lattice (SHBL) benchmark.

    Key innovations:
      - Uses spherical harmonics to create rotationally symmetric basins.
      - Homogeneous basin sizes via Fourier synthesis on a lattice.
      - Smooth, differentiable landscape with exact volume uniformity.
      - Tiny radial bias for unique global minimum at origin.
    """

    def __init__(self, dim):
        self.dim = int(dim)
        if self.dim < 2:
            raise ValueError("SphericalHarmonicBasinLattice requires dim >= 2.")

        # Domain parameters
        self.lo, self.hi = -5.0, 5.0
        self.L = self.hi - self.lo

        # Lattice spacing (calibrated for homogeneity)
        self.s = max(1.8, self.L / 4.5)

        # Spherical harmonic parameters
        self.l_max = 3  # Maximum degree
        self.m_max = 3   # Maximum order
        self.depth = 10.0

        # Basis functions for spherical harmonics
        self._precompute_harmonics()

        # Tiny bias for unique minimum
        self.bias = 1e-4

    def _precompute_harmonics(self):
        """Precompute spherical harmonic basis functions."""
        self.harmonics = []
        for l in range(0, self.l_max + 1):
            for m in range(-l, l + 1):
                # Store (l, m) and normalization factor
                norm = np.sqrt((2*l + 1) * (4*np.pi) / (4*np.pi))
                self.harmonics.append((l, m, norm))

    def f(self, x):
        """Evaluate objective at x."""
        x = np.asarray(x, dtype=float)
        if x.ndim == 1:
            return float(self._eval_one(x))
        return np.array([self._eval_one(xi) for xi in x])

    def _eval_one(self, x):
        # Find nearest lattice center
        cx, cy = self._nearest_lattice_center(x)

        # Vector from center to point (in 2D plane)
        dx = x[0] - cx
        dy = x[1] - cy

        # Polar coordinates
        r = np.sqrt(dx*dx + dy*dy + 1e-15)
        theta = np.arctan2(dy, dx)

        # Spherical harmonic expansion (sum over l, m)
        Y_sum = 0.0
        for l, m, norm in self.harmonics:
            if m == 0:
                Y_lm = norm * np.sqrt(1/(4*np.pi)) * np.ones_like(theta)
            else:
                # Real spherical harmonics (cosine and sine terms)
                Y_lm_cos = norm * np.sqrt(2) * np.cos(m * theta)
                Y_lm_sin = norm * np.sqrt(2) * np.sin(m * theta)
                Y_lm = Y_lm_cos if m > 0 else Y_lm_sin

            # Associated Legendre polynomial (simplified for small l)
            P_lm = self._assoc_legendre(l, abs(m), np.cos(theta))
            Y_sum += P_lm * Y_lm

        # Basin energy with harmonic scaling
        E = self.depth * (1 - r / self.s) ** 2 if r <= self.s else 0.0
        E *= Y_sum  # Modulate with spherical harmonics

        # Tiny bias for unique minimum at origin
        bias_term = self.bias * np.dot(x, x)

        return float(E + bias_term)

    def _assoc_legendre(self, l, m, x):
        """Simplified associated Legendre polynomial for small l."""
        if l == 0:
            return np.ones_like(x)
        elif l == 1 and m == 0:
            return x
        elif l == 1 and m == 1:
            return -np.sqrt(1 - x*x)
        elif l == 2 and m == 0:
            return 0.5 * (3*x*x - 1)
        elif l == 2 and m == 1:
            return -3 * x * np.sqrt(1 - x*x)
        elif l == 2 and m == 2:
            return 3 * (1 - x*x)
        else:
            return np.zeros_like(x)

    def _nearest_lattice_center(self, x):
        """Find nearest lattice center in 2D plane."""
        cx = self.s * np.round((x[0] + 5.0) / self.s) - 5.0
        cy = self.s * np.round((x[1] + 5.0) / self.s) - 5.0
        return float(cx), float(cy)
